# AUTO-GENERATED BY silc __COMPILER_VERSION__ — DO NOT EDIT
"""Silc embed worker: tensor::infer feeds and `query nearest` (ADR-010).

Serves JSON over HTTP on a Unix socket (SILC_EMBED_SOCKET) to the Bun app
worker and the Go loop kernel:

  POST /embed    {"texts": [...]}                         -> {"vectors": [[...], ...]}
  POST /nearest  {"table", "needle" | "vector", "limit"}  -> {"rows": [...]}
  GET  /health                                            -> {"ok": true, ...}

Embeds never call silclm and are never model calls. Vectors live in the row's
`vector_embedding` field in app.db; they are never written to the loop event
log, so a replay recomputes them. `nearest` ranks with sqlite-vec cosine
distance, best first, capped at MAX_LIMIT. It scans the table; there is no
approximate index.
"""
import json
import os
import socketserver
import sqlite3
import sys
from http.server import BaseHTTPRequestHandler

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

from embedding_models import load_model  # noqa: E402

MODEL_SPEC = json.loads(r'''__EMBED_MODEL_JSON__''')
NEAREST_TABLES = json.loads(r'''__EMBED_NEAREST_JSON__''')
MAX_LIMIT = __EMBED_MAX_LIMIT__
MAX_TEXTS = 256
MAX_BODY_BYTES = 8 * 1024 * 1024
SOCKET_PATH = os.environ.get("SILC_EMBED_SOCKET", "")
DB_PATH = os.environ.get("SILC_DB_PATH", "data/app.db")

_model = None


def model():
    global _model
    if _model is None:
        _model = load_model(MODEL_SPEC)
    return _model


def embed_texts(texts):
    if not isinstance(texts, list) or not all(isinstance(t, str) for t in texts):
        raise ValueError("texts must be a list of strings")
    if len(texts) > MAX_TEXTS:
        raise ValueError(f"at most {MAX_TEXTS} texts per request")
    return model().embed(texts)


def open_db():
    import sqlite_vec

    conn = sqlite3.connect(DB_PATH, timeout=5.0)
    conn.enable_load_extension(True)
    sqlite_vec.load(conn)
    conn.enable_load_extension(False)
    conn.execute("PRAGMA busy_timeout = 5000")
    return conn


def nearest(body):
    table = body.get("table")
    field = NEAREST_TABLES.get(table) if isinstance(table, str) else None
    if not field:
        raise ValueError(f"table {table!r} does not declare `query nearest`")
    limit = body.get("limit")
    if not isinstance(limit, int) or isinstance(limit, bool) or limit < 1:
        raise ValueError("limit must be a positive integer")
    limit = min(limit, MAX_LIMIT)
    vector = body.get("vector")
    if vector is None:
        needle = body.get("needle")
        if not isinstance(needle, str):
            raise ValueError("needle must be a string")
        if not needle.strip():
            return []
        vector = embed_texts([needle])[0]
    if not isinstance(vector, list) or len(vector) != MODEL_SPEC["dimension"]:
        raise ValueError(f"vector must have {MODEL_SPEC['dimension']} floats")
    path = f"$.{field}"
    conn = open_db()
    try:
        exists = conn.execute(
            "SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = ?", (table,)
        ).fetchone()
        if not exists:
            return []
        rows = conn.execute(
            f"""
            SELECT id, data,
                   vec_distance_cosine(vec_f32(json_extract(data, ?)), vec_f32(?)) AS distance
            FROM "{table}"
            WHERE json_type(data, ?) = 'array' AND json_array_length(data, ?) = ?
            ORDER BY distance ASC, created_at DESC
            LIMIT ?
            """,
            (path, json.dumps(vector), path, path, MODEL_SPEC["dimension"], limit),
        ).fetchall()
    finally:
        conn.close()
    out = []
    for row_id, data, distance in rows:
        record = json.loads(data)
        record.pop(field, None)
        out.append({"id": row_id, **record, "_score": round(1.0 - float(distance), 6)})
    return out


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def address_string(self):
        return "silc-embed"

    def log_message(self, format, *args):  # noqa: A002
        return

    def _send(self, status, payload):
        body = json.dumps(payload, separators=(",", ":")).encode()
        self.send_response(status)
        self.send_header("content-type", "application/json")
        self.send_header("content-length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self):  # noqa: N802
        if self.path == "/health":
            self._send(
                200,
                {"ok": True, "model": MODEL_SPEC["id"], "dimension": MODEL_SPEC["dimension"]},
            )
        else:
            self._send(404, {"error": "not found"})

    def do_POST(self):  # noqa: N802
        length = int(self.headers.get("content-length") or 0)
        if length > MAX_BODY_BYTES:
            self._send(413, {"error": "request too large"})
            return
        try:
            body = json.loads(self.rfile.read(length) or b"{}")
            if self.path == "/embed":
                self._send(200, {"vectors": embed_texts(body.get("texts"))})
            elif self.path == "/nearest":
                self._send(200, {"rows": nearest(body)})
            else:
                self._send(404, {"error": "not found"})
        except ValueError as exc:
            self._send(400, {"error": str(exc)})
        except Exception as exc:  # noqa: BLE001
            self._send(500, {"error": str(exc)})


class Server(socketserver.ThreadingMixIn, socketserver.UnixStreamServer):
    daemon_threads = True


def main():
    if not SOCKET_PATH:
        raise SystemExit("SILC_EMBED_SOCKET is not set")
    try:
        os.unlink(SOCKET_PATH)
    except FileNotFoundError:
        pass
    if MODEL_SPEC["provider"] == "onnx-cpu":
        model()
    with Server(SOCKET_PATH, Handler) as server:
        os.chmod(SOCKET_PATH, 0o600)
        print(
            f"silc: embed worker ready ({MODEL_SPEC['id']}, {MODEL_SPEC['dimension']}-d)",
            file=sys.stderr,
            flush=True,
        )
        server.serve_forever()


if __name__ == "__main__":
    main()
